import subprocess, itertools, sys, os
W="/app/warriors"
def make(nmov,dec,b,m,path="/tmp/cand/v.red"):
    lines=[f";redcode-94\n;name V\n;assert CORESIZE == 8000 && MAXCYCLES == 80000\n",
           "dec equ %d\n"%dec,"gate equ clear-4\n","        org clear-1\n",
           "bptr dat bomb, %d\n"%b,"bomb spl #dec, %d\n"%m]
    for _ in range(nmov):
        lines.append("     mov *bptr, >gate\n")
    lines.append("     djn.f clear, }bomb\n     end\n")
    open(path,"w").write("".join(lines))
    return path
def run(nmov,dec,b,m):
    p=make(nmov,dec,b,m)
    res={}
    for o in ["stone","vampire","paper","snake","g2-clear"]:
        out=subprocess.run(["pmars","-b","-r","100","-f",p,f"{W}/{o}.red"],capture_output=True,text=True).stdout
        ln=[l for l in out.splitlines() if l.startswith("Results:")][-1]
        res[o]=int(ln.split()[1])
    margins={"stone":res["stone"]-75,"vampire":res["vampire"]-75,"paper":res["paper"]-75,"snake":res["snake"]-33,"g2-clear":res["g2-clear"]-33}
    return res,min(margins.values())
if __name__=="__main__":
    nmov=int(sys.argv[1])
    best=[]
    for dec in [7999,7998,7990,7985,7970,4000,6667,2667]:
        for b in [9,12,14,16,20,24]:
            for m in [7,11,15,17,20,22]:
                r,mm=run(nmov,dec,b,m)
                best.append((mm,dec,b,m,r))
    best.sort(reverse=True)
    for x in best[:12]:
        print(x)
